  function patch(frame,width,height,x,y){x=Math.round(x);y=Math.round(y);if(x<SIZE||y<SIZE||x>=width-SIZE||y>=height-SIZE)return null;const data=[];for(let j=-SIZE;j<=SIZE;j++)for(let i=-SIZE;i<=SIZE;i++)data.push(frame[(y+j)*width+x+i]);const mean=data.reduce((a,b)=>a+b,0)/data.length;const centered=data.map(v=>v-mean);const energy=Math.sqrt(centered.reduce((a,b)=>a+b*b,0)/data.length);return {data:centered,energy,x,y};}
