      if(points.length===2){const results=points.map(p=>track(frame,320,240,p.reference,p));if(results.every(p=>p.valid)&&now-lastAt<500){points=points.map((p,i)=>({...p,...results[i]}));const a=points[0],b=points[1],distance=Math.hypot(a.x-b.x,a.y-b.y),angle=Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI,similarity=Math.min(...points.map(p=>p.confidence));status(c().tracking);host.querySelector('[data-lc-metrics]').textContent=c().angle+' '+angle.toFixed(0)+'° · '+c().distance+' '+distance.toFixed(0)+' '+c().unit+' · '+c().confidence+' '+(similarity*100).toFixed(0)+'%';}else{points=[];status(c().lost);host.querySelector('[data-lc-metrics]').textContent='';}}
